const startConference = `-- name: StartConference :one
UPDATE conferences
SET status = 'live', started_at = COALESCE(started_at, now()), ended_at = NULL, updated_at = now()
WHERE id = $1 AND status <> 'live'
RETURNING id, workspace_id, task_id, created_by, title, description, scheduled_at, started_at, ended_at, status, recording_ttl_days, created_at, updated_at, soon_notified_for, duration_minutes, recurrence, timezone, milestone_id
`

// StartConference (re)activates a room. It is idempotent on purpose: everyone's
// client calls join at once when a meeting begins, and the first caller is
// whoever's network was fastest — the COALESCE keeps started_at at that first
// join instead of letting the last racer overwrite it. status <> 'live' (rather
// than = 'scheduled') is what makes a conference reusable (#2879): a call that
// was paused back to 'scheduled' — or a legacy 'ended' one — starts again on the
// next join instead of being a dead room. ended_at is cleared so a restarted
// call does not carry the previous session's end time.
func (q *Queries) StartConference(ctx context.Context, id uuid.UUID) (Conference, error) {
	row := q.db.QueryRow(ctx, startConference, id)
	var i Conference
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TaskID,
		&i.CreatedBy,
		&i.Title,
		&i.Description,
		&i.ScheduledAt,
		&i.StartedAt,
		&i.EndedAt,
		&i.Status,
		&i.RecordingTtlDays,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SoonNotifiedFor,
		&i.DurationMinutes,
		&i.Recurrence,
		&i.Timezone,
		&i.MilestoneID,
	)
	return i, err
}

const updateConference = `-- name: UpdateConference :one
UPDATE conferences
SET title = $2, description = $3, scheduled_at = $4, task_id = $5, recording_ttl_days = $6,
    duration_minutes = $7, recurrence = $8, timezone = $9, milestone_id = $10, updated_at = now()
WHERE id = $1
RETURNING id, workspace_id, task_id, created_by, title, description, scheduled_at, started_at, ended_at, status, recording_ttl_days, created_at, updated_at, soon_notified_for, duration_minutes, recurrence, timezone, milestone_id
`

type UpdateConferenceParams struct {
	ID               uuid.UUID  `json:"id"`
	Title            string     `json:"title"`
	Description      string     `json:"description"`
	ScheduledAt      *time.Time `json:"scheduled_at"`
	TaskID           *uuid.UUID `json:"task_id"`
	RecordingTtlDays int32      `json:"recording_ttl_days"`
	DurationMinutes  *int32     `json:"duration_minutes"`
	Recurrence       string     `json:"recurrence"`
	Timezone         string     `json:"timezone"`
	MilestoneID      *uuid.UUID `json:"milestone_id"`
}

// UpdateConference is a full replace of the editable fields (the same shape the
// other Update handlers in this codebase use); status transitions have their own
// statements below so a PATCH of the title can never take a call off the air.
func (q *Queries) UpdateConference(ctx context.Context, arg UpdateConferenceParams) (Conference, error) {
	row := q.db.QueryRow(ctx, updateConference,
		arg.ID,
		arg.Title,
		arg.Description,
		arg.ScheduledAt,
		arg.TaskID,
		arg.RecordingTtlDays,
		arg.DurationMinutes,
		arg.Recurrence,
		arg.Timezone,
		arg.MilestoneID,
	)
	var i Conference
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TaskID,
		&i.CreatedBy,
		&i.Title,
		&i.Description,
		&i.ScheduledAt,
		&i.StartedAt,
		&i.EndedAt,
		&i.Status,
		&i.RecordingTtlDays,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SoonNotifiedFor,
		&i.DurationMinutes,
		&i.Recurrence,
		&i.Timezone,
		&i.MilestoneID,
	)
	return i, err
}

